// #6a993d794918a5e83bc3231b (#c3231b) AC6, FL-05 шаг 1 — экран входа: RTL, фокус в «מייל», видимый фокус по Tab (кейс AUTH-LG-001).
// #172fd7d688f4438bdadda900 (#dda900) — фокус в «מייל» при загрузке + текст «הכניסה בהזמנה בלבד…»: те же проверки.
// spec: specs/auth-login.md (1.1) · seed: tests/seed.spec.ts (гость). Только чтение, без сети входа — @prod-safe.
import { test, expect } from '../../fixtures';

test.describe('Экран входа (#6a993d794918a5e83bc3231b)', () => {
  test('гость: /login — dir=rtl, фокус в «מייל», видимый фокус по Tab, вход по приглашению @desktop @prod-safe #6a993d794918a5e83bc3231b #172fd7d688f4438bdadda900', async ({ page }) => {
    await page.goto('/login');
    await expect(page.getByRole('heading', { level: 1, name: 'כניסה לחשבון' })).toBeVisible();

    // AC6 «מוצג בכיווניות מימין לשמאל».
    await expect(page.locator('html')).toHaveAttribute('dir', 'rtl');
    await expect(page.locator('html')).toHaveAttribute('lang', 'he');
    const form = page.locator('form');
    expect(await form.evaluate((el) => getComputedStyle(el).direction)).toBe('rtl');

    // FL-05 «המסך נטען עם טופס ריק ומיקוד בשדה המייל».
    const email = page.getByRole('textbox', { name: 'מייל' });
    await expect(email).toBeFocused();
    await expect(email).toHaveValue('');
    await expect(email).toHaveAttribute('type', 'email');
    await expect(email).toHaveAttribute('autocomplete', 'username');

    // AC6 «עם מיקוד מקלדת נראה לעין»: каждый элемент по Tab — :focus-visible с видимой обводкой.
    const order = [
      page.getByLabel('סיסמה', { exact: true }),
      page.getByRole('button', { name: 'הצגה' }),
      page.getByRole('link', { name: 'שכחתי סיסמה' }),
      page.getByRole('button', { name: 'כניסה', exact: true }),
    ];
    for (const el of order) {
      await page.keyboard.press('Tab');
      await expect(el).toBeFocused();
      const ring = await el.evaluate((node) => {
        const s = getComputedStyle(node);
        return {
          focusVisible: node.matches(':focus-visible'),
          outline: s.outlineStyle !== 'none' && parseFloat(s.outlineWidth) > 0,
          shadow: s.boxShadow !== 'none',
        };
      });
      expect(ring.focusVisible, 'элемент в фокусе с клавиатуры').toBe(true);
      expect(ring.outline || ring.shadow, 'видимая обводка фокуса (outline или box-shadow)').toBe(true);
    }

    // FL-05 / FL-08 шаг 2: вход только по приглашению, регистрации нет; путь к сбросу и поддержке.
    await expect(page.getByText('הכניסה בהזמנה בלבד. אין לכם חשבון? בקשו הזמנה ממנהל החשבון בעסק.')).toBeVisible();
    await expect(page.getByRole('link', { name: 'שכחתי סיסמה' })).toHaveAttribute('href', '/forgot-password');
    await expect(page.getByRole('link', { name: 'פנייה לתמיכה' })).toHaveAttribute('href', /^mailto:/);
    await expect(page.getByRole('link', { name: /הרשמה|יצירת חשבון/ })).toHaveCount(0);
  });
});
